    const texSw = (kind, base) => { try { return `background-image:url(${V3.texCanvas(kind, base, 96).toDataURL()});background-color:${base}`; } catch (e) { return `background:${base}`; } };
    h += sec('Sols int\u00e9rieurs', 'floor', Object.entries(MATS).filter(([, m]) => !m.ext).map(([k, m]) => [k, m.n]), k => texSw(MATS[k].tex === 'tiles' ? 'tiles' : MATS[k].tex, MATS[k].c));
    h += sec('Sols ext\u00e9rieurs', 'floor', Object.entries(MATS).filter(([, m]) => m.ext).map(([k, m]) => [k, m.n]), k => texSw(MATS[k].tex === 'tiles' ? 'pavers' : MATS[k].tex, MATS[k].c));
