function markTiles() { $$('#lib .tile[data-kind]').forEach(t => t.setAttribute('aria-pressed', !!(pending && pending.kind === t.dataset.kind && pending.key === t.dataset.k))); $$('#lib .mt').forEach(t => t.setAttribute('aria-pressed', !!(pending && pending.kind === 'mat' && pending.key === t.dataset.k && pending.mk === t.dataset.mk))); }
cv.addEventListener('dragover', e => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; });
cv.addEventListener('drop', e => { e.preventDefault(); const d = e.dataTransfer.getData('text/plain'); const p = toW(e.clientX, e.clientY); const [kind, a, b] = d.split(':'); if (kind === 'furn' && FURN[a]) placeFurn(a, p); else if (kind === 'open' && OPDEF[a]) addOpeningAt(p, a); else if (kind === 'model' && P.models[a]) applyPending({ kind: 'model', key: a }, p); else if (kind === 'mat') applyMaterial(a, b, p); });
function makeThumbs() { if (!has3D) return; let r; try { const c = document.createElement('canvas'); c.width = 160; c.height = 120; r = new THREE.WebGLRenderer({ canvas: c, antialias: true, alpha: true, preserveDrawingBuffer: true }); } catch (e) { return; }
  r.outputEncoding = THREE.sRGBEncoding; const keys = Object.keys(FURN).filter(k => !FURN[k].stair); let i = 0; const LT = TP.View3D;
  const step = () => { if (i >= keys.length) { r.dispose(); return; } const k = keys[i++], d = FURN[k]; try { const sc = new THREE.Scene(); sc.add(new THREE.HemisphereLight(0xffffff, 0x888888, 1.1)); const dl = new THREE.DirectionalLight(0xffffff, .9); dl.position.set(2, 4, 3); sc.add(dl);
      const g = LT._furn3D ? LT._furn3D({ id: k, type: k, w: d.w, d: d.d, h: d.h || 80, c: d.c, z: 0 }) : null; if (g) { sc.add(g); const bb = new THREE.Box3().setFromObject(g), sz = bb.getSize(new THREE.Vector3()), ctr = bb.getCenter(new THREE.Vector3()), s = Math.max(sz.x, sz.y, sz.z) || 1; const cam = new THREE.PerspectiveCamera(30, 4 / 3, .01, 100); cam.position.set(ctr.x + s * 1.35, ctr.y + s * 1.05, ctr.z + s * 1.7); cam.lookAt(ctr); r.setClearColor(0, 0); r.render(sc, cam); thumbs[k] = r.domElement.toDataURL('image/png'); $$(`.tile[data-k="${k}"] .th`).forEach(th => { th.innerHTML = `<img alt="" src="${thumbs[k]}">`; }); }
      sc.traverse(o => { if (o.geometry) o.geometry.dispose(); }); } catch (e) { } setTimeout(step, 0); }; step(); }

