$('#rtEnv').addEventListener('click', () => showPTab('env')); $('#rtProps').addEventListener('click', () => showPTab('props')); $('#rtCalc').addEventListener('click', () => showPTab('calc')); $('#rtAI').addEventListener('click', () => showPTab('ai'));
