const swatches = (id, list, cur) => `<div class="sw" id="${id}">${list.map(([c, n]) => `<button style="background:${c}" data-c="${c}" title="${esc(n)}" aria-label="${esc(n)}" aria-pressed="${String(cur || '').toLowerCase() === c.toLowerCase()}"></button>`).join('')}</div>`;
