  let h = `<div class="psec"><h3>Synth\u00e8se</h3><div class="kpis"><div class="kpi hi"><span>Surface habitable nette</span><b>${fmtArea(S.hab)}</b></div><div class="kpi"><span>Emprise au sol</span><b>${fmtArea(S.footprint)}</b></div><div class="kpi"><span>Volume habitable</span><b>${fr(S.volume / 1e6, 0)} m\u00b3</b></div><div class="kpi"><span>Toiture</span><b>${fr(S.roofArea / 1e4, 1)} m\u00b2</b></div><div class="kpi"><span>Fa\u00e7ades</span><b>${fr(S.facade / 1e4, 1)} m\u00b2</b></div><div class="kpi"><span>Ext\u00e9rieurs</span><b>${fmtArea(S.ext)}</b></div></div></div>`;
  h += `<div class="psec"><h3>Estimation indicative de construction</h3><div class="row">${Object.entries(GAMMES).map(([k, g]) => `<button class="btn sm${P.gamme === k ? ' pri' : ''}" data-gamme="${k}">${g.n}</button>`).join('')}</div><div class="kpis"><div class="kpi hi"><span>Construction</span><b>${eur(C.build)}</b></div><div class="kpi"><span>Prix au m\u00b2</span><b>${eur(C.perM2)}</b></div></div><p class="note">Fourchette de ${eur(C.low)} \u00e0 ${eur(C.high)}, hors terrain, frais et raccordements. Mobilier en plus : ${eur(C.furn)}.</p><div class="tw"><table class="rec"><tbody>` + C.lots.filter(l => l.v > 0).map(l => `<tr><td>${l.n}<div class="bar" style="width:${Math.max(2, l.v / maxLot * 100)}%"></div></td><td class="n">${eur(l.v)}</td></tr>`).join('') + `<tr class="tot"><td>Total construction</td><td class="n">${eur(C.build)}</td></tr></tbody></table></div></div>`;
  h += `<div class="psec"><h3>Nomenclature des pi\u00e8ces</h3><div class="tw"><table class="rec"><thead><tr><th>Pi\u00e8ce</th><th class="n">Nette</th><th class="n">Volume</th></tr></thead><tbody>`;
  for (const lv of sortedLevels(P)) { const rs = S.rooms.filter(r => r.level === lv.name && !r.ext); if (!rs.length) continue; h += `<tr class="lot"><td colspan="3">${esc(lv.name)}</td></tr>` + rs.map(r => `<tr><td>${esc(r.name)}${r.hab ? '' : ' <small style="color:var(--ink-2)">(non habitable)</small>'}<br><small style="color:var(--ink-2)">${MATS[r.mat].n}</small></td><td class="n">${fr(r.net / 1e4)} m\u00b2</td><td class="n">${fr(r.vol / 1e6, 1)} m\u00b3</td></tr>`).join(''); }
  h += `<tr class="tot"><td>Habitable</td><td class="n">${fr(S.hab / 1e4)} m\u00b2</td><td class="n">${fr(S.volume / 1e6, 0)} m\u00b3</td></tr></tbody></table></div></div>`;
  const byKind = {}; S.openings.forEach(o => { const k = `${o.n} ${fmtLen(o.w)} \u00d7 ${fmtLen(o.h)}`; byKind[k] = (byKind[k] || 0) + 1; });
  h += `<div class="psec"><h3>Ouvertures (L \u00d7 H, ${P.unit})</h3><div class="tw"><table class="rec"><tbody>` + (Object.keys(byKind).length ? Object.entries(byKind).sort().map(([k, n]) => `<tr><td>${esc(k)}</td><td class="n">${n}</td></tr>`).join('') : '<tr><td>Aucune ouverture.</td></tr>') + '</tbody></table></div></div>';
  h += `<div class="psec"><h3>M\u00e9tr\u00e9 approximatif</h3><div class="tw"><table class="rec"><tbody>`; let lot = '';
  for (const q of S.quantities) { if (q.val <= 0) continue; if (q.lot !== lot) { lot = q.lot; h += `<tr class="lot"><td colspan="2">${esc(lot)}</td></tr>`; } h += `<tr><td>${esc(q.item)}${q.note ? `<br><small style="color:var(--ink-2)">${esc(q.note)}</small>` : ''}</td><td class="n">${q.unit === 'u' || q.unit === 'plaques' || q.unit === 'L' ? Math.round(q.val).toLocaleString('fr-FR') : fr(q.val, q.val < 10 ? 2 : 1)} ${q.unit}</td></tr>`; }
  h += `</tbody></table></div></div><div class="psec"><h3>Exporter les tableaux</h3><div class="row"><button class="btn sm" data-csv="rooms">Pi\u00e8ces (.csv)</button><button class="btn sm" data-csv="open">Ouvertures (.csv)</button><button class="btn sm" data-csv="qty">M\u00e9tr\u00e9 et co\u00fbt (.csv)</button><button class="btn sm" data-csv="furn">Mobilier (.csv)</button></div><button class="btn pri" id="calcDossier">Dossier complet du projet (.zip)</button></div>`;
