  const gc = { grass: '#6F8F4C', meadow: '#86A35A', alpine: '#7E9658', dry: '#B9AE6C', tropical: '#4E8C3C', forest: '#4F6B3A', desert: '#D7B184', snow: '#EEF2F6' }[g] || '#6F8F4C';
  if (['mountains', 'valley', 'summit', 'cliff'].includes(rel) && w !== 'sea') { s += '<path d="M0 34 L14 16 L24 26 L38 8 L52 24 L64 12 L78 26 L96 14 L96 40 L0 40Z" fill="#8B93A0"/><path d="M33 14 L38 8 L43 14 L40 13 L37 15Z M60 16 L64 12 L68 16Z M92 16 L96 14 L96 18Z" fill="#F4F6F8"/>'; }
  if (rel === 'dunes') s += '<path d="M0 36 Q20 24 40 34 T96 30 L96 54 L0 54Z" fill="#E2BE8C"/><path d="M0 44 Q28 32 56 42 T96 40 L96 54 L0 54Z" fill="#D0A574"/>';
